2026-08-08 11:48:29,979 [INFO ] [main] com.armedia.acm.services.ocr.rules.OCRRulesTest - DRL: {}package OCR_Rules;
//generated from Decision Table
import java.text.SimpleDateFormat;
import com.armedia.acm.services.mediaengine.model.MediaEngine;
import java.util.Date;
import java.util.Calendar;
import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
function String dateFormat(String fmt)
{
  SimpleDateFormat dateFormat = new SimpleDateFormat(fmt);
  Date now = new Date();
  return dateFormat.format(now);
}

function Boolean evalSpring(String expression, Object obj)
{
    ExpressionParser ep = new SpelExpressionParser();
    Expression exp = ep.parseExpression(expression);
    EvaluationContext ec = new StandardEvaluationContext();

    Boolean evaluated = exp.getValue(ec, obj, Boolean.class);

    return evaluated;
}
// rule values at C20, header at C15
rule "OCR Rules_20"
	salience 65535
	when
		$ocr: MediaEngine(eval(evalSpring("status == null", $ocr)))
	then
		$ocr.setStatus('DRAFT');
end

// rule values at C21, header at C15
rule "OCR Rules_21"
	salience 65534
	when
		$ocr: MediaEngine(eval(evalSpring("remoteId == null && type == 'AUTOMATIC'", $ocr)))
	then
		$ocr.setRemoteId('ocr-' + dateFormat('yyyyMMddHHmmssSSS') + '-' + $ocr.getId());
end

// rule values at C22, header at C15
rule "OCR Rules_22"
	salience 65533
	when
		$ocr: MediaEngine(eval(evalSpring("language == null", $ocr)))
	then
		$ocr.setLanguage('eng');
end


